def find_kth_smallest(arr1, arr2, k):
    """
    Returns the k-th smallest element in the union of two sorted arrays.
    Time Complexity: O(log(min(m, n))) which satisfies O(log(m+n)).
    Space Complexity: O(1)
    """
    def get_kth(arr1, start1, end1, arr2, start2, end2, k):
        # Ensure arr1 is the smaller array to optimize
        if len(arr1[start1:end1+1]) > len(arr2[start2:end2+1]):
            return get_kth(arr2, start2, end2, arr1, start1, end1, k)

        if start1 > end1:
            return arr2[start2 + k - 1]
        if k == 1:
            return min(arr1[start1], arr2[start2])

        mid1 = (end1 - start1) // 2
        mid2 = (end2 - start2) // 2
        val1 = arr1[start1 + mid1] if mid1 < len(arr1) - start1 else float('inf')
        val2 = arr2[start2 + mid2] if mid2 < len(arr2) - start2 else float('inf')

        if val1 > val2:
            if k // 2 <= mid2 + 1:
                return get_kth(arr1, start1, end1, arr2, start2 + k // 2, end2, k - k // 2)
            else:
                return get_kth(arr1, start1, end1, arr2, start2, end2, k - k // 2)
        else:
            if k // 2 <= mid1 + 1:
                return get_kth(arr1, start1 + k // 2, end1, arr2, start2, end2, k - k // 2)
            else:
                return get_kth(arr1, start1, end1, arr2, start2, end2, k - k // 2)

    return get_kth(arr1, 0, len(arr1) - 1, arr2, 0, len(arr2) - 1, k)
